export const tagNames={sea:'Море рядом',beach:'Пляжи',work:'Коворкинги и кафе',metro:'Метро',malls:'Торговые центры',clubs:'Компьютерные клубы',mountains:'Горы и природа'};
export const defaultFilters={search:'',region:'',income:'',people:1,maxRent:'',housing:'',tags:[],visaFree:false,longStay:false,easyStay:false,verifiedOnly:false,bureaucracy:'',russian:false,english:false,climate:'',funding:'income',savings:'',months:7,reserve:false,citizenship:'',sort:'recommended',saved:false};
export function monthly(city,people=1,housing='',reserve=false){const rent=Math.round(city.rent*(housing==='house'?1.8:housing==='condo'?1.15:1)*(1+Math.max(0,people-2)*.2));const daily=Math.round(city.living*(1+Math.max(0,people-1)*.7));return {rent,daily,total:Math.round((rent+daily)*(reserve?1.2:1)),reserve:reserve?Math.round((rent+daily)*.2):0};}
export function findMatches(countries,f,rates,saved=[]){const rate=rates[f.currency]||1;let query=f.search.trim().toLowerCase().replaceAll('ё','е');if(['куда угодно','весь мир','любая страна'].includes(query))query='';const hits=[];for(const c of countries){if(f.region&&!(f.region==='Азия'?['ЮВА','Восточная Азия','Южная Азия','Центральная Азия','Ближний Восток','Кавказ'].includes(c.region):c.region===f.region))continue;if(f.saved&&!saved.includes(c.id))continue;if(f.visaFree&&!c.visaFree||f.longStay&&c.longType==='unknown'||f.easyStay&&c.longType!=='free'||f.verifiedOnly&&!c.verified||f.russian&&!c.russian||f.english&&!c.english||f.climate&&c.climate!==f.climate||f.bureaucracy&&(!c.difficulty||c.difficulty>Number(f.bureaucracy))||f.citizenship&&(!c.citizenYears||c.citizenYears>Number(f.citizenship)))continue;const cities=c.cities.filter(city=>{if(query&&!`${c.name} ${c.region} ${city.name} ${city.wiki.replaceAll('_',' ')} ${c.region==='ЮВА'?'юго-восточная азия':''} ${['ЮВА','Восточная Азия','Южная Азия','Центральная Азия','Ближний Восток','Кавказ'].includes(c.region)?'азия':''}`.toLowerCase().replaceAll('ё','е').includes(query))return false;if(f.housing&&!city.housing.includes(f.housing))return false;if(f.tags.some(t=>!city.tags.includes(t)))return false;const m=monthly(city,+f.people,f.housing,f.reserve);if(f.maxRent!==''&&m.rent>Number(f.maxRent)/rate)return false;if(f.funding==='income'&&f.income!==''&&m.total>Number(f.income)/rate)return false;if(f.funding==='savings'&&f.savings!==''&&m.total*Number(f.months)+m.rent*2>Number(f.savings)/rate)return false;return true});if(cities.length){const city=cities.reduce((a,b)=>monthly(a,+f.people,f.housing).total<=monthly(b,+f.people,f.housing).total?a:b);hits.push({country:c,cities,city,budget:monthly(city,+f.people,f.housing,f.reserve)})}}if(f.sort==='budget')hits.sort((a,b)=>a.budget.total-b.budget.total);if(f.sort==='rent')hits.sort((a,b)=>a.budget.rent-b.budget.rent);if(f.sort==='name')hits.sort((a,b)=>a.country.name.localeCompare(b.country.name,'ru'));if(f.sort==='legal')hits.sort((a,b)=>(a.country.difficulty||9)-(b.country.difficulty||9));return hits;}
